def roc_auc(y_true, scores):
    if len(y_true) != len(scores):
        raise ValueError("labels and scores must have the same length")
    positives = sum(1 for y in y_true if y == 1)
    negatives = len(y_true) - positives
    if positives == 0 or negatives == 0:
        raise ValueError("AUC needs both classes")

    order = sorted(range(len(scores)), key=lambda i: scores[i])
    rank_sum = 0.0          # sum of the (1-based) ranks of the positives, tied scores sharing their average rank
    start = 0
    while start < len(order):
        end = start
        while end + 1 < len(order) and scores[order[end + 1]] == scores[order[start]]:
            end += 1
        average_rank = (start + end) / 2 + 1
        rank_sum += average_rank * sum(1 for i in order[start:end + 1] if y_true[i] == 1)
        start = end + 1
    return (rank_sum - positives * (positives + 1) / 2) / (positives * negatives)
